/* EUTOPIA Automotive — generated by tools/build.py */

(function(){
  var view = document.getElementById('view');
  var hdr  = document.getElementById('hdr');
  var pages = ['home','about','services','servicing','repairs','contact','terms','privacy'];
  var current = null;
  var io = null;

  /* ---------- ⊖ stroke-draw preparation ---------- */
  function prepDraw(scope){
    scope.querySelectorAll('.draw').forEach(function(svg){
      svg.querySelectorAll('circle,line').forEach(function(el){
        var len = 80;
        try { if (el.getTotalLength) len = el.getTotalLength(); } catch(e){}
        el.style.strokeDasharray  = len;
        if (!svg.classList.contains('in')) el.style.strokeDashoffset = len;
      });
    });
  }

  /* ---------- Reveal on scroll ---------- */
  function initReveal(page){
    if (io) io.disconnect();
    var items = page.querySelectorAll('.rv, .rv-img');
    items.forEach(function(el){ el.classList.remove('in'); });
    page.querySelectorAll('.draw').forEach(function(d){
      if (!d.closest('.formpanel')) d.classList.remove('in');
    });
    prepDraw(page);

    if (!('IntersectionObserver' in window)){
      items.forEach(function(el){ el.classList.add('in'); });
      page.querySelectorAll('.draw').forEach(function(d){ d.classList.add('in'); });
      return;
    }
    var groups = new Map();
    io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if (!entry.isIntersecting) return;
        var el = entry.target, parent = el.parentElement;
        var n = groups.get(parent) || 0;
        groups.set(parent, n + 1);
        setTimeout(function(){
          el.classList.add('in');
          el.querySelectorAll('.draw').forEach(function(d){ d.classList.add('in'); });
        }, Math.min(n, 6) * 80);
        io.unobserve(el);
      });
    }, {threshold:0.12, rootMargin:'0px 0px -8% 0px'});
    items.forEach(function(el){ io.observe(el); });
  }

  /* ---------- Sticky header ---------- */
  var lightTop = false;
  function onScroll(){
    if (lightTop) { hdr.classList.add('stuck'); return; }
    var trigger = window.innerHeight * 0.75;
    hdr.classList.toggle('stuck', window.scrollY > trigger);
  }
  window.addEventListener('scroll', onScroll, {passive:true});

  /* ---------- Router ---------- */
  function idFromHash(){
    var fixed = document.body.getAttribute('data-page'); if (fixed) return fixed;
    var h = (location.hash || '').replace('#/','').trim();
    return pages.indexOf(h) > -1 ? h : 'home';
  }

  function show(id, animate){
    var page = document.getElementById('page-' + id);
    if (!page) return;
    document.querySelectorAll('.page').forEach(function(p){ p.classList.remove('active'); });
    page.classList.add('active');
    current = id;
    lightTop = page.hasAttribute('data-light-top');

    document.querySelectorAll('[data-nav]').forEach(function(a){
      a.classList.toggle('on', a.getAttribute('data-nav') === id);
    });

    if (animate !== false) window.scrollTo(0, 0);
    onScroll();
    initReveal(page);

    /* A hash route change is invisible to assistive tech unless focus moves
       and the title updates. Both are required for a real multi-page build. */
    var titles = {
      home:'Car Service & Repairs in Cape Town | EUTOPIA Automotive',
      about:'About Us | EUTOPIA Automotive',
      services:'Our Services | EUTOPIA Automotive',
      servicing:'Car Servicing in Cape Town | EUTOPIA Automotive',
      repairs:'Car Repairs & Diagnostics | EUTOPIA Automotive',
      contact:'Contact Us | EUTOPIA Automotive',
      terms:'Terms & Conditions | EUTOPIA Automotive',
      privacy:'Privacy Policy | EUTOPIA Automotive'
    };
    if (!document.body.getAttribute('data-page')) document.title = titles[id] || titles.home;
    document.body.className = document.body.className.replace(/\bpage-\S+/g,'').trim() + ' page-' + id;
    if (animate !== false) view.focus({preventScroll:true});
  }

  function route(){
    var id = idFromHash();
    if (id === current) return;
    if (current === null){ show(id, false); return; }
    view.classList.add('leaving');
    setTimeout(function(){
      show(id);
      view.classList.remove('leaving');
    }, 350);
  }

  window.addEventListener('hashchange', route);

  /* ---------- Tabs (WAI-ARIA tab pattern) ---------- */
  document.querySelectorAll('[data-tabs]').forEach(function(group, gi){
    var tabs = Array.prototype.slice.call(group.querySelectorAll('.tab'));

    /* Wire aria-controls / labelledby so the panel is announced with its tab */
    tabs.forEach(function(t, i){
      var key = t.getAttribute('data-tab');
      var panel = group.querySelector('.panel[data-panel="' + key + '"]');
      if (!panel) return;
      t.id = 'tab-' + gi + '-' + i;
      panel.id = 'panel-' + gi + '-' + i;
      t.setAttribute('aria-controls', panel.id);
      panel.setAttribute('aria-labelledby', t.id);
    });

    function select(btn, focus){
      var key = btn.getAttribute('data-tab');
      tabs.forEach(function(t){
        var on = (t === btn);
        t.classList.toggle('active', on);
        t.setAttribute('aria-selected', on ? 'true' : 'false');
        t.setAttribute('tabindex', on ? '0' : '-1');
      });
      group.querySelectorAll('.panel').forEach(function(p){
        p.classList.toggle('active', p.getAttribute('data-panel') === key);
      });
      if (focus) btn.focus();
      /* keep the selected tab in view when the strip scrolls on mobile */
      if (btn.scrollIntoView) btn.scrollIntoView({block:'nearest', inline:'nearest'});
    }

    group.addEventListener('click', function(e){
      var btn = e.target.closest('.tab');
      if (btn) select(btn, false);
    });

    group.addEventListener('keydown', function(e){
      var btn = e.target.closest('.tab');
      if (!btn) return;
      var i = tabs.indexOf(btn), next = null;
      if (e.key === 'ArrowRight') next = tabs[(i + 1) % tabs.length];
      else if (e.key === 'ArrowLeft') next = tabs[(i - 1 + tabs.length) % tabs.length];
      else if (e.key === 'Home') next = tabs[0];
      else if (e.key === 'End') next = tabs[tabs.length - 1];
      if (next){ e.preventDefault(); select(next, true); }
    });
  });

  /* ---------- Forms: associate every label with its control ---------- */
  document.querySelectorAll('.field').forEach(function(field, i){
    var label = field.querySelector('label');
    var input = field.querySelector('input, select, textarea');
    if (!label || !input) return;
    var id = input.id || ('f-' + i + '-' + Math.random().toString(36).slice(2,7));
    input.id = id;
    label.setAttribute('for', id);
    /* iOS zooms any input under 16px on focus */
    if (parseFloat(getComputedStyle(input).fontSize) < 16) input.style.fontSize = '16px';
  });

  /* ---------- Mobile menu ---------- */
  var mBtn = document.getElementById('menuBtn');
  var mNav = document.getElementById('mobileNav');

  function setMenu(open){
    mNav.classList.toggle('open', open);
    mBtn.textContent = open ? 'Close' : 'Menu';
    mBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    mBtn.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    document.body.style.overflow = open ? 'hidden' : '';   /* no scrolling behind the overlay */
    if (open){ var first = mNav.querySelector('a'); if (first) first.focus(); }
    else { mBtn.focus(); }
  }

  mBtn.addEventListener('click', function(){ setMenu(!mNav.classList.contains('open')); });
  mNav.addEventListener('click', function(e){ if (e.target.tagName === 'A') setMenu(false); });
  document.addEventListener('keydown', function(e){
    if (e.key === 'Escape' && mNav.classList.contains('open')) setMenu(false);
  });

  /* ---------- Booking links scroll to the form on the current page ---------- */
  document.addEventListener('click', function(e){
    var a = e.target.closest('[data-book]');
    if (!a) return;
    e.preventDefault();
    var target = document.querySelector('.page.active .formpanel');
    if (!target || !target.offsetParent) target = document.getElementById('booking');
    target.scrollIntoView({behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block:'start'});
    setTimeout(function(){ var f = target.querySelector('input'); if (f) f.focus({preventScroll:true}); }, 600);
  });

  /* ---------- Marque carousel pause / play ---------- */
  document.querySelectorAll('.marquee-toggle').forEach(function(btn){
    btn.addEventListener('click', function(){
      var wrap = btn.closest('.marquee-wrap');
      var paused = wrap.classList.toggle('paused');
      btn.setAttribute('aria-pressed', paused ? 'true' : 'false');
      btn.setAttribute('aria-label', paused ? 'Play the logo carousel' : 'Pause the logo carousel');
    });
  });

  /* ---------- Back to top ---------- */
  (function(){
    var btn = document.querySelector('.to-top'); if (!btn) return;
    function toggle(){ btn.classList.toggle('show', window.scrollY > window.innerHeight * 0.9); }
    window.addEventListener('scroll', toggle, {passive:true}); toggle();
    btn.addEventListener('click', function(){
      var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
      window.scrollTo({top:0, behavior: reduce ? 'auto' : 'smooth'});
      /* return keyboard focus to the top of the page too */
      setTimeout(function(){ var v = document.getElementById('view'); if (v) v.focus({preventScroll:true}); }, reduce ? 0 : 600);
    });
  })();

  /* ---------- Booking form: validate, submit to /api/booking, show receipt ---------- */
  (function(){
    var form = document.getElementById('bookingForm'); if (!form) return;
    var panel = document.getElementById('bookingSuccess');
    var btn = form.querySelector('button[type="submit"]'), btnText = btn.textContent;
    var status = form.querySelector('.form-status');
    var stamp = function(){ form.elements.t.value = String(Date.now()); };
    stamp();
    var preview = !/^https?:$/.test(location.protocol) || /claude\.ai|claudeusercontent|anthropic/i.test(location.hostname);
    var LABELS = {first_name:'first name', email:'email address', mobile:'mobile number'};

    function setError(name, msg){
      var el = document.getElementById('err-' + name), input = form.elements[name];
      if (el) el.textContent = msg || '';
      if (input){ var f = input.closest('.field'); if (f) f.classList.toggle('invalid', !!msg);
        if (msg) input.setAttribute('aria-invalid','true'); else input.removeAttribute('aria-invalid'); }
    }
    function clearErrors(){ ['first_name','last_name','email','mobile','make','model','year','service','message'].forEach(function(n){ setError(n,''); }); status.textContent=''; }
    function check(d){
      var e = {};
      ['first_name','email','mobile'].forEach(function(n){ if(!d[n] || !d[n].trim()) e[n] = 'Please enter your ' + LABELS[n] + '.'; });
      if (!e.email && !/^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[a-z]{2,}$/i.test(d.email.trim())) e.email = 'Please enter a valid email address.';
      if (!e.mobile){ var dg = d.mobile.replace(/[^\d]/g,''); if (dg.length < 9 || dg.length > 15) e.mobile = 'Please enter a valid phone number.'; }
      if (d.year && !/^(19[5-9]\d|20\d\d)$/.test(d.year.trim())) e.year = 'Please enter a four-digit year.';
      return e;
    }
    function showErrors(e){
      var first = null;
      Object.keys(e).forEach(function(n){ setError(n, e[n]); if (!first) first = n; });
      if (first && form.elements[first]) form.elements[first].focus();
      status.textContent = 'Please check the highlighted fields.';
    }
    function success(res, d, isPreview){
      var set = function(k, v){ var el = panel.querySelector('[data-s="'+k+'"]'); if (el) el.textContent = v; };
      set('name', d.first_name.trim()); set('ref', res.reference); set('mobile', d.mobile.trim());
      set('receipt', res.receiptSent === false
        ? 'Your request has reached us, but we couldn’t deliver a confirmation email to ' + d.email.trim() + ' — please check the address.'
        : 'A confirmation with a copy of your request has been sent to ' + d.email.trim() + '. If it isn’t in your inbox in a few minutes, check your spam or promotions folder.');
      panel.querySelector('[data-s="preview"]').hidden = !isPreview;
      form.hidden = true; panel.hidden = false;
      panel.scrollIntoView({block:'center', behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth'});
      setTimeout(function(){ panel.focus({preventScroll:true}); }, 350);
    }
    panel.querySelector('[data-s="again"]').addEventListener('click', function(){
      form.reset(); clearErrors(); stamp(); panel.hidden = true; form.hidden = false; form.elements.first_name.focus();
    });
    form.addEventListener('input', function(e){ if (e.target.name) setError(e.target.name, ''); });
    form.addEventListener('submit', function(ev){
      ev.preventDefault(); clearErrors();
      var d = {}; new FormData(form).forEach(function(v, k){ d[k] = typeof v === 'string' ? v : ''; });
      d.page = location.href;
      var e = check(d); if (Object.keys(e).length) return showErrors(e);
      btn.disabled = true; btn.textContent = 'Sending…';
      var done = function(){ btn.disabled = false; btn.textContent = btnText; };
      if (preview){ return setTimeout(function(){ done(); success({reference:'EUT-PREVIEW', receiptSent:true}, d, true); }, 800); }
      fetch('/api/booking', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(d)})
        .then(function(r){ return r.json().catch(function(){ return {}; }).then(function(j){ return {r:r, j:j}; }); })
        .then(function(x){
          done();
          if (x.r.ok && x.j.ok) return success(x.j, d, false);
          if (x.j.errors) return showErrors(x.j.errors);
          status.textContent = x.j.error || 'Something went wrong sending your request. Please call +27 87 265 3684 or WhatsApp 079 670 1967.';
        })
        .catch(function(){ done(); status.textContent = 'We couldn’t reach our server. Please check your connection, or call +27 87 265 3684 / WhatsApp 079 670 1967.'; });
    });
  })();

  /* ---------- Forms are mockups ---------- */
  document.addEventListener('click', function(e){
    var b = e.target.closest('.formpanel .btn');
    if (b) e.preventDefault();
  });

  route();
  /* the booking band lives outside the routed pages */
  (function(){
    var qb = document.getElementById('booking'); if (!qb || !('IntersectionObserver' in window)) return;
    qb.querySelectorAll('.draw circle,.draw line').forEach(function(){});
    var o = new IntersectionObserver(function(es){ es.forEach(function(en){
      if (!en.isIntersecting) return;
      var i = 0; qb.querySelectorAll('.rv').forEach(function(el){ setTimeout(function(){ el.classList.add('in'); el.querySelectorAll('.draw').forEach(function(d){d.classList.add('in');}); if (el.classList.contains('draw')) el.classList.add('in'); }, (i++)*80); });
      o.disconnect(); }); }, {threshold:.12});
    o.observe(qb);
  })();
})();
